#include <vector>
#include <list>

int main() {
    std::vector<int> v = {1, 2, 3};
    std::vector<int> source = {10, 11};

    // Get iterator to middle element
    auto it_v = v.begin() + 1;

    // Insert range. All iterators/references after insertion point are invalid
    v.insert(it_v, source.begin(), source.end()); 

    // it_v is now INVALIDATED, referencing the original '2' is undefined behavior.

    std::list<int> l = {1, 2, 3};
    auto it_l = l.begin();
    ++it_l;

    l.insert(it_l, source.begin(), source.end());
    // it_l remains VALID, still pointing to the original '2' element.
}
